import {NextResponse} from "next/server";import {authContext} from "../../../../lib/server-auth";
function slugify(v:string){return v.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"").slice(0,48)||"external"}
export async function POST(req:Request){try{const {s,workspaceId}=await authContext(req),b=await req.json(),name=String(b.name||"Landing externe").trim().slice(0,120),productId=String(b.product_id||"").trim(),domain=String(b.domain||"").trim().toLowerCase().replace(/^https?:\/\//,"").split("/")[0];if(!productId)return NextResponse.json({error:"Produit requis"},{status:400});const {data:product}=await s.from("products").select("id").eq("id",productId).eq("workspace_id",workspaceId).eq("is_active",true).is("archived_at",null).maybeSingle();if(!product)return NextResponse.json({error:"Produit introuvable"},{status:404});const slug=slugify(name)+"-ext-"+crypto.randomUUID().replace(/-/g,"").slice(0,8),seo={source:"external",external_domain:domain,external_created_at:new Date().toISOString()};const {data,error}=await s.from("landing_pages").insert({workspace_id:workspaceId,product_id:productId,name,slug,status:"PUBLISHED",locale:"fr",published_at:new Date().toISOString(),seo}).select("id,name,slug,status,product_id,seo").single();if(error)throw error;return NextResponse.json({page:data},{status:201})}catch(e:any){return NextResponse.json({error:e.message},{status:e.message==="Non autorisé"?401:500})}}
